Regional API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(regional_api_gateway_bff, "Regional API Gateway / BFF") {
    Component(Routing_Geo_Enforcement_Middleware, "Routing & Geo-Enforcement Middleware", "Node.js", "Enforces strict regional data residency and geo-compliance for incoming requests.")
    Component(GraphQL_Resolvers, "GraphQL Resolvers", "Node.js, GraphQL", "Handles flexible data fetching and client requests for low-bandwidth rural clients.")
    Component(Audit_Telemetry_Interceptor, "Audit & Telemetry Interceptor", "Node.js", "Captures audit logs and telemetry data, forwarding them to monitoring services.")
    Component(Client_Context_Policy_Injector, "Client Context & Policy Injector", "Node.js", "Injects necessary client context and policy constraints into downstream service calls.")
}

Rel(Routing_Geo_Enforcement_Middleware, GraphQL_Resolvers, "Routes validated requests to", "")
Rel(GraphQL_Resolvers, Audit_Telemetry_Interceptor, "Triggers telemetry tracking via", "")
Rel(Client_Context_Policy_Injector, GraphQL_Resolvers, "Applies context to", "")

@enduml

Consent & Policy Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Consent & Policy Engine container

Container_Boundary(consent_policy_engine, "Consent & Policy Engine") {
    Component(Consent_Policy_Engine, "Consent & Policy Engine", ".NET 8 / ASP.NET Core", "Enforces strict regional data residency, purpose-based consent, and evaluates local policy caches.")
}

System_Ext(Regional_WORM_Storage, "Regional WORM Storage", "Compliance and policy storage")
System_Ext(Regional_Memorystore_Redis, "Regional Memorystore (Redis)", "Local policy caches and Pub/Sub revocations")

Rel(Consent_Policy_Engine, Regional_WORM_Storage, "Stores compliance and policy records securely", "TLS 1.3, Cloud KMS")
Rel(Consent_Policy_Engine, Regional_Memorystore_Redis, "Evaluates local policy caches and handles real-time Pub/Sub revocations", "TCP, TLS")

@enduml

FHIR & Prescription Integration Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhiring_container, "FHIR & Prescription Integration Service") {
    Component(PrescriptionOrchestrator, "Prescription Orchestrator", ".NET Core", "Orchestrates the workflow for processing cross-border e-prescriptions.")
    Component(FHIRAdapter, "FHIR Adapter", ".NET Core", "Adapts and standardizes data formats to the FHIR standard.")
    Component(EUGatewayAdapter, "EU Gateway Adapter", ".NET Core", "Interfaces with National e-Prescription Gateways in the EU.")
    Component(ValidationMappingValidator, "Validation & Mapping Validator", ".NET Core", "Validates and maps payload data for regulatory compliance.")
    Component(MassTransitNotificationEventConsumer, "MassTransit & Notification Event Consumer", "MassTransit / .NET Core", "Consumes asynchronous events and ensures reliable message processing.")
}

Rel(PrescriptionOrchestrator, MassTransitNotificationEventConsumer, "Communicates via", "In-Process Bus")

@enduml
